diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..7bd760e
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,69 @@
+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { t } from "../i18n/messages.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { consume } from "../domain/batches.js";
+import { isDate } from "../dates.js";
+
+/** Imports a whole sales file atomically, skipping previously imported tickets. */
+export function importSales(store, text) {
+  const rows = [];
+  for (const [index, line] of text.split(/\r?\n/).entries()) {
+    if (!line.trim()) continue;
+    const fields = [];
+    let value = "";
+    let quoted = false;
+    let closed = false;
+    for (let i = 0; i < line.length; i++) {
+      const ch = line[i];
+      if (quoted) {
+        if (ch === '"' && line[i + 1] === '"') { value += '"'; i++; }
+        else if (ch === '"') { quoted = false; closed = true; }
+        else value += ch;
+      } else if (ch === ",") { fields.push(value); value = ""; closed = false; }
+      else if (ch === '"' && !value && !closed) quoted = true;
+      else if (ch === '"' || closed) throw new AppError("bad_request", { reason: `row ${index + 1}: invalid CSV` });
+      else value += ch;
+    }
+    if (quoted) throw new AppError("bad_request", { reason: `row ${index + 1}: invalid CSV` });
+    fields.push(value);
+    rows.push({ fields, number: index + 1 });
+  }
+  const header = rows.shift()?.fields ?? [];
+  const columns = ["ticket", "soldAt", "dishId", "qty"];
+  if (header.length !== columns.length || columns.some((c, i) => header[i]?.trim() !== c))
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty" });
+  const copy = memoryStore(store.data);
+  const existing = new Set(copy.data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const { fields, number } of rows) {
+    const where = `row ${number}`;
+    try {
+      if (fields.length !== 4) throw new AppError("bad_request", { reason: "expected four columns" });
+      const [ticket, instant, dishText, qtyText] = fields.map((f) => f.trim());
+      if (!ticket) throw new AppError("bad_request", { reason: "ticket is required" });
+      if (!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)$/.test(instant) || !Number.isFinite(Date.parse(`${instant.slice(0, 10)}T00:00:00Z`)) || !isDate(instant.slice(0, 10)) || !Number.isFinite(Date.parse(instant)))
+        throw new AppError("bad_request", { reason: "invalid soldAt" });
+      if (!/^[1-9]\d*$/.test(dishText) || !Number.isSafeInteger(Number(dishText))) throw new AppError("bad_request", { reason: "invalid dishId" });
+      if (!/^[1-9]\d*$/.test(qtyText) || !Number.isSafeInteger(Number(qtyText))) throw new AppError("bad_request", { reason: "invalid qty" });
+      const dish = getDish(copy, Number(dishText));
+      const recipe = getRecipe(copy, dish.recipeId);
+      const ingredients = scaled(recipe, Number(qtyText));
+      if (existing.has(ticket)) continue;
+      const soldAt = new Date(instant).toISOString();
+      for (const ingredient of ingredients) {
+        if (ingredient.qty > 0) consume(copy, ingredient.itemId, ingredient.qty, { at: soldAt, ref: `sale:${ticket}` });
+      }
+      copy.data.sales.push({ ticket, soldAt, dishId: dish.id, qty: Number(qtyText), ingredients });
+      tickets.add(ticket);
+      dishes += Number(qtyText);
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("bad_request", { reason: `${where}: ${t(error.code, "en", error.params)}` });
+    }
+  }
+  store.data = copy.data;
+  return { tickets: tickets.size, dishes };
+}
